@Pseudo
@Mixin(targets={"com.erchien.arcanevortex.Content.Item.EntityRemover.EntityRemover","com.erchien.arcanevortex.Content.Item.LittleWoodenSword.LittleWoodenSword","com.erchien.arcanevortex.Content.Item.Sword.AlpacaDivineBlade","com.erchien.arcanevortex.Content.Item.Sword.BlackMeteorRainbowTrace","com.erchien.arcanevortex.Content.Item.Sword.Crimson","com.erchien.arcanevortex.Content.Item.Sword.FallenBlade","com.erchien.arcanevortex.Content.Item.Sword.FoxBlade.FoxBlade","com.erchien.arcanevortex.Content.Item.Sword.Odin","com.erchien.arcanevortex.Content.Item.Sword.OrangeSummer.OrangeSummer","com.erchien.arcanevortex.Content.Item.Sword.Overlord","com.erchien.arcanevortex.Content.Item.Sword.PestilenceSting","com.erchien.arcanevortex.Content.Item.Sword.PrismalAbyss","com.erchien.arcanevortex.Content.Item.Sword.RelicBrassSword","com.erchien.arcanevortex.Content.Item.Sword.StellarVortex","com.erchien.arcanevortex.Content.Item.Sword.ZSWJ.ZSWJ","com.erchien.arcanevortex.Content.Item.TestSword.TestSword","com.erchien.arcanevortex.Content.Item.VanSh.VanShFinalFantasy.VanShFinalFantasy","com.erchien.arcanevortex.Content.Item.VanSh.VanShTool.VanSh","com.erchien.arcanevortex.Content.Item.VanSh.VanShTool.VanShRadiantSun"},priority=2000,remap=false)
public abstract class ArcaneWeaponGuard {
 @Inject(method="onLeftClickEntity(Lnet/minecraft/world/item/ItemStack;Lnet/minecraft/world/entity/player/Player;Lnet/minecraft/world/entity/Entity;)Z",at=@At("HEAD"),cancellable=true,remap=false,require=0)
 private void avLeft(net.minecraft.world.item.ItemStack stack,net.minecraft.world.entity.player.Player source,net.minecraft.world.entity.Entity target,CallbackInfoReturnable<Boolean> ci){dev.starcrown.DollAuthority.onAttack(source,target);if(dev.starcrown.DivineCombat.rejectCompatibility(target,"AV.item.leftClick"))ci.setReturnValue(true);}
 @Inject(method={"hurtEnemy(Lnet/minecraft/world/item/ItemStack;Lnet/minecraft/world/entity/LivingEntity;Lnet/minecraft/world/entity/LivingEntity;)Z","m_7579_(Lnet/minecraft/world/item/ItemStack;Lnet/minecraft/world/entity/LivingEntity;Lnet/minecraft/world/entity/LivingEntity;)Z"},at=@At("HEAD"),cancellable=true,remap=false,require=0)
 private void avHit(net.minecraft.world.item.ItemStack stack,net.minecraft.world.entity.LivingEntity target,net.minecraft.world.entity.LivingEntity source,CallbackInfoReturnable<Boolean> ci){dev.starcrown.DollAuthority.onAttack(source,target);if(dev.starcrown.DivineCombat.rejectCompatibility(target,"AV.item.hurtEnemy"))ci.setReturnValue(false);}
}
